def rle_encode(s):
    out, i = [], 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(s[i] + str(j - i))
        i = j
    return ''.join(out)

def is_balanced(s):
    st, m = [], {')':'(',']':'[','}':'{'}
    for c in s:
        if c in '([{':
            st.append(c)
        elif c in m:
            if not st or st.pop() != m[c]:
