def flatten(lst):
    out = []
    for x in lst:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

import re
def word_freq(text):
    out = {}
    for w in re.findall(r'[a-zA-Z]+', text):
        w = w.lower()
        out[w] = out.get(w, 0) + 1
    return out

def merge_intervals(intervals):
    out = []
    for a, b in sorted(intervals):
        if out and a <= out[-1][1]:
            out[-1][1] = max(out[-1][1], b)
        else:
            out.append([a, b])
    return out

def second_largest(nums):
    s = sorted(set(nums))
    return s[-2] if len(s) > 1 else None

def caesar(s, k):
    out = ''
    for c in s:
        if 'a' <= c <= 'z':
            out += chr((ord(c) - 97 + k) % 26 + 97)
        elif 'A' <= c <= 'Z':
            out += chr((ord(c) - 65 + k) % 26 + 65)
        else:
            out += c
    return out

def dedupe(lst):
    out = []
    for x in lst:
        if x not in out:
            out.append(x)
    return out

def binary_search(a, x):
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(a) and a[lo] == x else -1

def anagram_groups(words):
    g = {}
    for w in words:
        g.setdefault(''.join(sorted(w)), []).append(w)
    return sorted(sorted(v) for v in g.values())

import os
def common_prefix(strs):
    return os.path.commonprefix(strs) if strs else ''

def digit_root(n):
    while n > 9:
        n = sum(map(int, str(n)))
    return n

def snake_to_camel(s):
    p = [x for x in s.split('_') if x]
    return p[0] + ''.join(x.capitalize() for x in p[1:]) if p else ''

def days_in_month(year, month):
    if month == 2:
        return 29 if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0) else 28
    return 30 if month in (4, 6, 9, 11) else 31

def two_sum(nums, target):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return [i, j]
    return None

def rotate_list(lst, k):
    if not lst:
        return []
    k %= len(lst)
    return lst[-k:] + lst[:-k] if k else lst[:]
